676: // X-Hub-Signature-256 = "sha256=" + HMAC-SHA256 of the exact request bytes,
677: // keyed with the app secret.
678: export function isValidMetaSignature(
679:   rawBody: Buffer | undefined,
680:   signature: string | undefined,
681:   appSecret: <REDACTED> | undefined,
682: ): boolean {
683:   if (!rawBody || !signature || !appSecret) return false;
684:   const expected = Buffer.from(
685:     `sha256=${createHmac('sha256', appSecret).update(rawBody).digest('hex')}`,
686:   );
687:   const received = Buffer.from(signature.trim());
688:   return (
689:     received.length === expected.length && timingSafeEqual(received, expected)
690:   );
