693: // One event per message a customer sent or button they tapped. Echoes
694: // (messages the Page itself sent, including the bot's replies), deliveries and
695: // reads are dropped, so a reply never starts a workflow again.
696: export function parseMessengerEvents(body: unknown): TriggerEvent[] {
697:   const payload = body as { object?: unknown; entry?: unknown } | null;
698:   if (payload?.object !== 'page' || !Array.isArray(payload.entry)) return [];
699: 
700:   const events: TriggerEvent[] = [];
701:   for (const entry of payload.entry as Array<{
702:     id?: unknown;
703:     messaging?: unknown;
704:   }>) {
705:     if (typeof entry?.id !== 'string' || !Array.isArray(entry.messaging)) {
706:       continue;
707:     }
708:     for (const event of entry.messaging as MessagingEvent[]) {
709:       const senderId = event?.sender?.id;
710:       if (typeof senderId !== 'string') continue;
711:       const timestamp =
712:         typeof event.timestamp === 'number'
713:           ? new Date(event.timestamp).toISOString()
714:           : null;
715: 
716:       const postback = event.postback;
717:       if (postback && typeof postback.payload === 'string') {
718:         // The same tap is delivered again with the same mid, or, without one,
719:         // at the same time with the same payload.
720:         const mid = typeof postback.mid === 'string' ? postback.mid : null;
721:         events.push({
722:           id:
723:             mid ??
724:             `postback:${entry.id}:${senderId}:${String(event.timestamp)}:${postback.payload}`,
725:           json: {
726:             type: 'postback',
727:             message_id: mid,
728:             sender_id: senderId,
729:             page_id: entry.id,
730:             text: typeof postback.title === 'string' ? postback.title : '',
731:             payload: postback.payload,
732:             attachments: [],
733:             timestamp,
734:             raw: event,
735:           },
736:         });
737:         continue;
738:       }
739: 
740:       const message = event?.message;
741:       if (
742:         !message ||
743:         message.is_echo === true ||
744:         typeof message.mid !== 'string'
745:       ) {
746:         continue;
747:       }
748:       const quickReply = message.quick_reply?.payload;
749:       events.push({
750:         id: message.mid,
751:         json: {
752:           type: 'message',
753:           message_id: message.mid,
754:           sender_id: senderId,
755:           page_id: entry.id,
756:           text: typeof message.text === 'string' ? message.text : '',
757:           // Set when the customer tapped one of the quick replies.
758:           payload: typeof quickReply === 'string' ? quickReply : null,
759:           attachments: (message.attachments ?? []).map((attachment) => ({
760:             type: typeof attachment?.type === 'string' ? attachment.type : null,
761:             url:
762:               typeof attachment?.payload?.url === 'string'
763:                 ? attachment.payload.url
764:                 : null,
765:           })),
766:           timestamp,
767:           raw: event,
768:         },
769:       });
770:     }
771:   }
772:   return events;
773: }

