233:   private async call<T>(
234:     method: 'get' | 'post' | 'delete',
235:     path: string,
236:     params: Record<string, unknown>,
237:     data?: unknown,
238:     options: { idempotent?: boolean } = {},
239:   ): Promise<T> {
240:     try {
241:       const response = await axios.request<T>({
242:         method,
243:         url: `https://graph.facebook.com/${GRAPH_VERSION}/${path}`,
244:         params,
245:         data,
246:         timeout: REQUEST_TIMEOUT_MS,
247:       });
248:       return response.data;
249:     } catch (error) {
250:       throw toAppApiError(error, options.idempotent ?? true);
251:     }
252:   }
