254: 
255: interface GraphError {
256:   message?: string;
257:   code?: number;
258:   error_subcode?: number;
259: }
260: 
261: // Rate limits, timeouts and 5xx are retryable; Graph explains everything else.
262: // A call that is not idempotent (sending a message) is retried only when Graph
263: // refused it outright (rate limit): after a timeout or a 5xx it may already
264: // have been delivered, and a retry would send it twice.
265: export function toAppApiError(error: unknown, idempotent = true): AppApiError {
266:   if (!(error instanceof AxiosError)) {
267:     return new AppApiError(
268:       error instanceof Error ? error.message : 'Facebook request failed',
269:       false,
270:     );
271:   }
272:   if (!error.response) {
273:     return new AppApiError(
274:       `Facebook did not answer (${error.code ?? 'network error'})`,
275:       idempotent,
276:     );
277:   }
278: 
279:   const status = error.response.status;
280:   const graph = (error.response.data as { error?: GraphError } | undefined)
281:     ?.error;
282:   const code = graph?.code;
283:   if (code === 10 && graph?.error_subcode === 2018278) {
284:     return new AppApiError(
285:       'Messenger only allows replies within 24 hours of the customer’s last message',
286:       false,
287:     );
288:   }
289:   if (code === 551) {
290:     return new AppApiError(
291:       'This person is not available on Messenger right now',
292:       false,
293:     );
294:   }
295:   if (code === 190) {
296:     return new AppApiError(
297:       'The Facebook connection has expired; reconnect the credential',
298:       false,
299:     );
300:   }
301:   const rateLimited =
302:     status === 429 || code === 4 || code === 32 || code === 613;
303:   return new AppApiError(
304:     `Facebook API error (${status}): ${graph?.message ?? error.message}`,
305:     rateLimited || (idempotent && status >= 500),
306:   );
307: }

