29: // The one ingress for every package: the package handles the request
30: // (handshake, verification, parsing); every listener that accepts an event
31: // runs, each in its own execution. No app-specific code here.
32: @CommandHandler(ReceiveWebhookCommand)
33: export class ReceiveWebhookHandler implements ICommandHandler<ReceiveWebhookCommand> {
34:   private readonly logger = new Logger(ReceiveWebhookHandler.name);
35: 
36:   constructor(
37:     private readonly registry: PackageRegistry,
38:     private readonly repository: TriggerRepository,
39:     private readonly vault: CredentialVault,
40:     private readonly dedup: WebhookDedupPort,
41:     private readonly tests: TestEventStore,
42:     private readonly commandBus: CommandBus,
43:   ) {}
44: 
45:   async execute(command: ReceiveWebhookCommand): Promise<ReceiveWebhookResult> {
46:     const endpoint = await this.repository.findEndpoint(command.endpointId);
47:     const trigger = this.registry.trigger(endpoint?.nodeKey);
48:     if (!endpoint || !trigger) return { outcome: 'not-found' };
49: 
50:     let credential: Record<string, unknown> | null = null;
51:     if (endpoint.credentialId) {
52:       const stored = await this.vault.findOwned(
53:         endpoint.credentialId,
54:         endpoint.ownerId,
55:       );
56:       if (!stored) return { outcome: 'not-found' };
57:       credential = stored.secret;
58:     }
59: 
60:     const result = await trigger.webhook.handle({
61:       request: command.request,
62:       credential,
63:       data: endpoint.data,
64:     });
65:     if (result.events.length === 0) {
66:       return {
67:         outcome: 'handled',
68:         status: result.status,
69:         contentType: result.contentType,
70:         body: result.body ?? {
71:           success: true,
72:           data: { started: [], ignored: 0 },
73:         },
74:       };
75:     }
76: 
77:     const [listeners, tests] = await Promise.all([
78:       this.repository.listenersOfEndpoint(endpoint.id),
79:       this.tests.waitingFor(endpoint.id),
80:     ]);
81:     // A per-node URL nobody listens on is the caller's mistake (or the
82:     // workflow is off): worth a 404. Shared URLs (one Meta App) keep acking.
83:     if (
84:       listeners.length === 0 &&
85:       tests.length === 0 &&
86:       trigger.webhook.scope === 'node'
87:     ) {
88:       return { outcome: 'not-found' };
89:     }
90: 
91:     const accepts = (
92:       event: TriggerEvent,
93:       parameters: Record<string, unknown>,
94:     ) => trigger.webhook.accepts?.(event, parameters) ?? true;
95:     const started: string[] = [];
96:     let ignored = 0;
97:     const pendingTests = [...tests];
98: 
99:     for (const event of result.events) {
100:       await this.deliverTests(pendingTests, event, accepts);
101: 
102:       const matching = listeners.filter((listener) =>
103:         accepts(event, listener.parameters),
104:       );
105:       if (matching.length === 0) {
106:         ignored += 1;
107:         continue;
108:       }
109:       if (
110:         event.id &&
111:         !(await this.dedup.claim(
112:           `dedup:${endpoint.id}:${event.id}`,
113:           DEDUP_TTL_SECONDS,
114:         ))
115:       ) {
116:         ignored += 1;
117:         continue;
118:       }
119:       started.push(...(await this.run(matching, event)));
120:     }
121: 
122:     return {
123:       outcome: 'handled',
124:       status: result.status,
125:       contentType: result.contentType,
126:       body: result.body ?? { success: true, data: { started, ignored } },
127:     };
128:   }
129: 
130:   // Each waiting test takes the first event it accepts, then stops.
131:   private async deliverTests(
132:     pending: TestListen[],
133:     event: TriggerEvent,
134:     accepts: (
135:       event: TriggerEvent,
136:       parameters: Record<string, unknown>,
137:     ) => boolean,
138:   ) {
139:     for (const listen of [...pending]) {
140:       if (!accepts(event, listen.parameters)) continue;
141:       pending.splice(pending.indexOf(listen), 1);
142:       await this.tests.save({
143:         ...listen,
144:         status: 'received',
145:         event: event.json,
146:       });
147:     }
148:   }
149: 
150:   private async run(listeners: Listener[], event: TriggerEvent) {
151:     const started: string[] = [];
152:     for (const listener of listeners) {
153:       try {
154:         started.push(
155:           await this.commandBus.execute<EnqueueExecutionCommand, string>(
156:             new EnqueueExecutionCommand(listener.workflowVersionId, [
157:               { json: event.json },
158:             ]),
159:           ),
160:         );
161:       } catch (error) {
162:         // One workflow failing to start must not stop the others.
163:         this.logger.error(
164:           `Could not start workflow ${listener.workflowId}: ${
165:             error instanceof Error ? error.message : String(error)
166:           }`,
167:         );
168:       }
169:     }
170:     return started;
171:   }
172: }

