import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient({
  datasources: { db: { url: 'postgresql://postgres:postgres@localhost:5433/flowpilot?schema=public' } }
});

async function main() {
  // 1. Workflows
  const workflows = await prisma.workflow.findMany({
    orderBy: { updatedAt: 'desc' },
    take: 10,
    select: { id: true, name: true, active: true, currentVersionId: true, updatedAt: true },
  });
  console.log('=== WORKFLOWS ===');
  console.log(JSON.stringify(workflows, null, 2));

  // 2. Listeners
  const listeners = await (prisma as any).listener.findMany({
    select: { workflowId: true, workflowVersionId: true, nodeKey: true, endpointId: true, parameters: true },
  });
  console.log('\n=== LISTENERS ===');
  console.log(JSON.stringify(listeners, null, 2));

  // 3. Endpoints
  const endpoints = await (prisma as any).webhookEndpoint.findMany({
    select: { id: true, nodeKey: true, credentialId: true, ownerId: true },
  }).catch(() => 'model not found');
  console.log('\n=== ENDPOINTS ===');
  console.log(JSON.stringify(endpoints, null, 2));

  // 4. Recent executions
  const execs = await prisma.execution.findMany({
    orderBy: { startedAt: 'desc' },
    take: 15,
    select: { id: true, status: true, triggerType: true, startedAt: true, completedAt: true },
  });
  console.log('\n=== EXECUTIONS (last 15) ===');
  console.log(JSON.stringify(execs, null, 2));

  // 5. Failed execution nodes
  const failedNodes = await prisma.executionNode.findMany({
    where: { OR: [{ status: 'FAILED' }, { execution: { status: 'FAILED' } }] },
    orderBy: { createdAt: 'desc' },
    take: 20,
    select: { executionId: true, nodeId: true, nodeKey: true, status: true, error: true },
  }).catch((e: any) => `error: ${e.message}`);
  console.log('\n=== FAILED NODES ===');
  console.log(JSON.stringify(failedNodes, null, 2));

  await prisma.$disconnect();
}

main().catch(e => { console.error(e); process.exit(1); });

