25: export interface StartRunInput {
26:   version: WorkflowVersionForExecution;
27:   triggerType: TriggerType;
28:   triggeredById: string | null;
29:   // Input of the first node: [] for a manual run, the payload for a webhook.
30:   triggerItems: Item[];
