33: // Runs a published version node by node. Shared by the manual (synchronous)
34: // path and the queue processor (webhook).
35: export class WorkflowEngine {
36:   private readonly runner: NodeRunner;
37: 
38:   constructor(
39:     private readonly repository: ExecutionRepository,
40:     executors: INodeExecutor[],
41:     private readonly catalog: NodeCatalogPort,
42:   ) {
43:     this.runner = new NodeRunner(
44:       repository,
45:       new Map(executors.map((executor) => [executor.key, executor])),
46:     );
47:   }
48: 
49:   // Throws when the definition cannot be run, before anything is stored.
50:   plan(definition: unknown): GraphPlan {
51:     return buildGraphPlan(definition);
52:   }
53: 
54:   async createExecution(input: StartRunInput, startedAt: Date) {
55:     return this.repository.createExecution({
56:       workflowId: input.version.workflowId,
57:       workflowVersionId: input.version.id,
58:       triggerType: input.triggerType,
59:       triggeredById: input.triggeredById,
60:       // A manual run starts at once; a background one waits for the queue.
61:       status:
62:         input.triggerType === TriggerType.MANUAL
63:           ? ExecutionStatus.RUNNING
64:           : ExecutionStatus.QUEUED,
65:       startedAt,
66:       context:
67:         input.triggerType === TriggerType.MANUAL
68:           ? undefined
69:           : { triggerItems: input.triggerItems },
70:     });
71:   }
72: 
73:   async run(
74:     executionId: string,
75:     version: WorkflowVersionForExecution,
76:     triggerItems: Item[],
77:     startedAt: Date,
78:   ): Promise<ExecutionStatus> {
79:     // Stays FAILED if anything unexpected throws (e.g. the database), so the
80:     // execution is never left RUNNING.
81:     let finalStatus = ExecutionStatus.FAILED;
82:     try {
83:       finalStatus = await this.runNodes(executionId, version, triggerItems);
84:     } finally {
85:       const finishedAt = new Date();
86:       await this.repository.finishExecution(
87:         executionId,
88:         finalStatus,
89:         finishedAt,
90:         finishedAt.getTime() - startedAt.getTime(),
91:       );
92:     }
93:     return finalStatus;
94:   }
95: 
96:   private async runNodes(
97:     executionId: string,
98:     version: WorkflowVersionForExecution,
99:     triggerItems: Item[],
100:   ): Promise<ExecutionStatus> {
101:     const { order, incoming } = this.plan(version.definition);
102:     const definition = version.definition as WorkflowDefinition;
103:     const nodes = new Map(definition.nodes.map((node) => [node.id, node]));
104:     const names = buildNodeNameIndex(definition.nodes);
105:     // A malformed node without a key must fail on its own (no executor),
106:     // not break the catalog lookup for the whole run.
107:     const nodeKeys = definition.nodes
108:       .map((node) => node.data?.key)
109:       .filter((key): key is string => typeof key === 'string');
110:     const configSchemas = await this.catalog.getConfigSchemas([
111:       ...new Set(nodeKeys),
112:     ]);
113: 
114:     const runs: NodeRun[] = [];
115:     // Items per output of the nodes that ran; nodes that were skipped are absent.
116:     const produced = new Map<
117:       string,
118:       { outputs: Map<string, Item[]>; offsets: Map<string, number> }
119:     >();
120:     let status = ExecutionStatus.SUCCESS;
121: 
122:     for (const nodeId of order) {
123:       const node = nodes.get(nodeId)!;
124:       const configSchema = configSchemas.get(node.data?.key);
125: 
126:       // An edge is active when its source ran and sent items to the output it
127:       // leaves from; the main output of a single-output node is always active,
128:       // even when empty, so a filter that drops everything still lets the next
129:       // node run.
130:       let items: Item[] = triggerItems;
131:       const inputSources: ItemSource[] = [];
132:       const edges = incoming.get(nodeId) ?? [];
133:       if (edges.length > 0) {
134:         items = [];
135:         let activated = false;
136:         for (const edge of edges) {
137:           const upstream = produced.get(edge.source);
138:           const key = edgeOutput(edge);
139:           const sent = upstream?.outputs.get(key);
140:           if (!upstream || !sent) continue;
141:           if (key !== MAIN_OUTPUT && sent.length === 0) continue;
142:           const offset = upstream.offsets.get(key) ?? 0;
143:           sent.forEach((item, index) => {
144:             items.push(item);
145:             inputSources.push({ nodeId: edge.source, index: offset + index });
146:           });
147:           activated = true;
148:         }
149:         if (!activated) {
150:           const now = new Date();
151:           await this.repository.saveNodeLog(executionId, {
152:             nodeId: node.id,
153:             nodeKey: node.data?.key ?? 'unknown',
154:             status: 'SKIPPED',
155:             input: [],
156:             output: null,
157:             startedAt: now,
158:             finishedAt: now,
159:           });
160:           continue;
161:         }
162:       }
163: 
164:       const rawConfig =
165:         node.data?.config &&
166:         typeof node.data.config === 'object' &&
167:         !Array.isArray(node.data.config)
168:           ? (node.data.config as Record<string, unknown>)
169:           : {};
170:       const outputDefs = resolveOutputs(configSchema, rawConfig);
171:       const result = await this.runner.run({
172:         node,
173:         workflowId: version.workflowId,
174:         executionId,
175:         items,
176:         inputSources: edges.length > 0 ? inputSources : undefined,
177:         outputKeys: outputDefs.map((def) => def.key),
178:         runs,
179:         names,
180:         configSchema,
181:         credentialOwnerId: version.workflowOwnerId,
182:       });
183: 
184:       await this.repository.saveNodeLog(executionId, result.log);
185: 
186:       if (result.status === ExecutionStatus.FAILED) {
187:         status = ExecutionStatus.FAILED;
188:         break;
189:       }
190:       const offsets = new Map<string, number>();
191:       let offset = 0;
192:       for (const [key, sent] of result.outputs) {
193:         offsets.set(key, offset);
194:         offset += sent.length;
195:       }
196:       produced.set(node.id, { outputs: result.outputs, offsets });
197:       runs.push({
198:         nodeId: node.id,
199:         nodeName: typeof node.data.name === 'string' ? node.data.name : node.id,
200:         input: items,
201:         inputSources: edges.length > 0 ? inputSources : undefined,
202:         output: result.output,
203:       });
204:     }
205:     return status;
206:   }
207: }

