21: // Runs an action node of an integration package for each item: the engine
22: // resolves expressions and the credential, the package talks to the app.
23: export class PackageActionExecutor implements IPerItemExecutor<Parameters> {
24:   readonly runMode = 'per_item' as const;
25:   readonly key: string;
26: 
27:   constructor(
28:     private readonly node: ActionNode,
29:     private readonly sleep: Sleep = defaultSleep,
30:   ) {
31:     this.key = node.key;
32:   }
33: 
34:   // Required fields must not resolve to blank (e.g. an expression whose
35:   // field is missing in the item).
36:   parseConfig(raw: unknown): Parameters {
37:     const parameters = nodeParameters(raw);
38:     for (const property of this.node.properties) {
39:       if (!property.required) continue;
40:       const value = parameters[property.name];
41:       if (
42:         value === undefined ||
43:         value === null ||
44:         (typeof value === 'string' && value.trim() === '')
45:       ) {
46:         throw new Error(`${property.displayName} is required`);
47:       }
48:     }
49:     return parameters;
50:   }
51: 
52:   expectedConnectorKey(rawConfig: Record<string, unknown>): string | null {
53:     if (this.node.credentialType) return this.node.credentialType;
54:     const from = this.node.credentialTypeFrom;
55:     const chosen = from ? rawConfig[from.field] : undefined;
56:     return from && typeof chosen === 'string' && from.types.includes(chosen)
57:       ? chosen
58:       : null;
59:   }
60: 
61:   async executeItem(params: {
62:     config: Parameters;
63:     item: Item;
64:     credential: unknown;
65:   }): Promise<ItemJson | ItemJson[] | null> {
66:     const credential =
67:       params.credential && typeof params.credential === 'object'
68:         ? (params.credential as Record<string, unknown>)
69:         : null;
70:     if (this.node.credentialType && !credential) {
71:       throw new Error('Choose a credential for this node');
72:     }
73:     return this.withRetry(() =>
74:       this.node.execute({
75:         parameters: params.config,
76:         credential,
77:         item: { json: params.item.json },
78:       }),
79:     );
80:   }
81: 
82:   // Rate limits and outages are retried with a growing pause; anything else
83:   // (e.g. Messenger's 24-hour window, revoked access) fails at once.
84:   private async withRetry<T>(attempt: () => Promise<T>): Promise<T> {
85:     for (let retry = 0; ; retry += 1) {
86:       try {
87:         return await attempt();
88:       } catch (error) {
89:         const retryable = error instanceof AppApiError && error.retryable;
90:         if (!retryable || retry >= PackageActionLimits.MAX_RETRIES) throw error;
91:         await this.sleep(1000 * 2 ** retry);
92:       }
93:     }
94:   }
95: }
96: 
97: // Executors of every package node: a trigger passes its event on (the event
98: // is the run's input), an action runs per item.
99: export function packageExecutors(registry: PackageRegistry): INodeExecutor[] {
100:   return registry
101:     .allNodes()
102:     .map((node) =>
103:       node.kind === 'action'
104:         ? new PackageActionExecutor(node)
105:         : new PassThroughTriggerExecutor(node.key),
106:     );
107: }

