99:           nodeKey: node.data.key,
100:           status: ExecutionStatus.SUCCESS,
101:           input: items,
102:           output,
103:           startedAt,
104:           finishedAt: new Date(),
105:         },
106:         output,
107:         outputs,
108:         status: ExecutionStatus.SUCCESS,
109:       };
110:     } catch (error) {
111:       const message =
112:         error instanceof Error ? error.message : 'Node execution failed';
113:       return {
114:         log: {
115:           nodeId: node.id,
116:           nodeKey: node.data?.key ?? 'unknown',
117:           status: ExecutionStatus.FAILED,
118:           input: items,
119:           output: error instanceof ItemRunError ? error.summary : null,
120:           errorMessage: sanitizeErrorText(message),
121:           startedAt,
122:           finishedAt: new Date(),
123:         },
124:         output: [],
125:         outputs: new Map(),
