170:   private async runPerItem(
171:     executor: IPerItemExecutor,
172:     rawConfig: Record<string, unknown>,
173:     params: NodeRunParams,
174:   ): Promise<Map<string, Item[]>> {
175:     const { items } = params;
176:     const outputs = new Map<string, Item[]>(
177:       (params.outputKeys ?? [MAIN_OUTPUT]).map((key) => [key, []]),
