256:   private async resolveCredential(
257:     executor: INodeExecutor,
258:     rawConfig: Record<string, unknown>,
259:     ownerId: string,
260:   ): Promise<unknown> {
261:     const candidate = rawConfig.credential_id;
262:     if (candidate === undefined) return null;
263:     if (typeof candidate !== 'string' || !UUID_PATTERN.test(candidate)) {
264:       throw new BadRequestException('Invalid credential ID format');
265:     }
266: 
267:     const resolved = await this.repository.resolveCredential(
268:       candidate,
269:       ownerId,
270:     );
271:     if (!resolved) throw new Error('credential was not found');
272: 
273:     const expected = executor.expectedConnectorKey?.(rawConfig);
274:     if (expected && resolved.connectorKey !== expected) {
275:       throw new Error(
276:         `Credential does not belong to the "${expected}" connector`,
277:       );
278:     }
279:     return resolved.secret;
280:   }
