  console.log('REPLACED LF');
} else if (content.includes(target.replace(/\n/g, '\r\n'))) {
  fs.writeFileSync(path, content.replace(target.replace(/\n/g, '\r\n'), replacement.replace(/\n/g, '\r\n')), 'utf8');
  console.log('REPLACED CRLF');
} else {
  console.log('TARGET NOT FOUND');
}

