const targetStr = `      <div className="p-4 flex flex-col gap-4 overflow-y-auto flex-1">`;
const replacementStr = `      <Tabs defaultValue="config" className="flex-1 flex flex-col overflow-hidden">
        <div className="px-4 pt-2.5 border-b border-border bg-background">
          <TabsList className="grid grid-cols-2 h-8">
