            <TabsTrigger value="inspector" className="text-xs">Output Preview</TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value="config" className="p-4 flex flex-col gap-4 overflow-y-auto flex-1 m-0">`;

const closingTarget = `        {webhook && (
          <TestEventPanel
            key={selectedNode.id}
            workflowId={workflowId}
            nodeId={selectedNode.id}
            draftSaving={isSaving}
          />
        )}
      </div>`;

const closingReplacement = `        {webhook && (
          <TestEventPanel
            key={selectedNode.id}
            workflowId={workflowId}
            nodeId={selectedNode.id}
            draftSaving={isSaving}
          />
        )}
        </TabsContent>

        <TabsContent value="inspector" className="p-4 overflow-y-auto flex-1 m-0">
          <NodeOutputInspector
            nodeKey={nodeType.key}
            nodeName={nodeName}
          />
        </TabsContent>
      </Tabs>`;

const targetStrCRLF = targetStr.replace(/\n/g, '\r\n');
const replacementStrCRLF = replacementStr.replace(/\n/g, '\r\n');
const closingTargetCRLF = closingTarget.replace(/\n/g, '\r\n');
const closingReplacementCRLF = closingReplacement.replace(/\n/g, '\r\n');

if (content.includes(targetStr)) {
  content = content.replace(targetStr, replacementStr);
} else if (content.includes(targetStrCRLF)) {
  content = content.replace(targetStrCRLF, replacementStrCRLF);
}

if (content.includes(closingTarget)) {
  content = content.replace(closingTarget, closingReplacement);
} else if (content.includes(closingTargetCRLF)) {
  content = content.replace(closingTargetCRLF, closingReplacementCRLF);
}

fs.writeFileSync(filePath, content, 'utf8');
console.log('SUCCESSFULLY INSERTED TABS INTO PROPERTIESPANEL');

